import json
import os
import csv
import sys
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.json"

# ---------------- Load data ----------------
with open(os.path.join(DATA, "instance.json")) as f:
    inst = json.load(f)

dist = inst["distances"]
term_pts = {tp["id"]: tp["distance_matrix_index"] for tp in inst["terminal_points"]}
caregivers = inst["caregivers"]
patients = inst["patients"]
horizon = inst["metadata"]["horizon"]
cost = inst["metadata"]["cost_components"]
lunch_win = inst["lunch_breaks"]

def read_csv(name):
    with open(os.path.join(DATA, name)) as f:
        return list(csv.DictReader(f))

profiles = {r["caregiver_id"]: r for r in read_csv("caregiver_profiles.csv")}
pattrs = {r["patient_id"]: r for r in read_csv("patient_attributes.csv")}
svc_req = {r["service_id"]: r for r in read_csv("service_requirements.csv")}
kits = {r["kit_id"]: r for r in read_csv("equipment_kits.csv")}
handoffs = read_csv("handoff_rules.csv")
restock_rules = {r["kit_id"]: r for r in read_csv("kit_restock_rules.csv")}
history = {r["caregiver_id"]: r for r in read_csv("caregiver_history.csv")}

# ---------------- Build tasks ----------------
# task = (patient, service)
tasks = []
task_info = {}
for p in patients:
    pid = p["id"]
    for rs in p["required_services"]:
        t = (pid, rs["service"])
        tasks.append(t)
        task_info[t] = {
            "patient": pid,
            "service": rs["service"],
            "dur": rs["duration"],
            "optional": p["optional"],
            "loc": p["distance_matrix_index"],
            "tw": p["time_windows"],
            "attrs": pattrs.get(pid, {}),
        }

C = [c["id"] for c in caregivers]
careg = {c["id"]: c for c in caregivers}
T = tasks
TIDX = {t: i for i, t in enumerate(T)}
NPOS = 10  # max positions per caregiver (13 tasks total, 4 caregivers)
M = 1200.0

def svc_cleanup(s):
    r = svc_req.get(s, {})
    try:
        return float(r.get("cleanup_after_contact", 0) or 0)
    except (TypeError, ValueError):
        return 0.0

def svc_kit(s):
    r = svc_req.get(s, {})
    k = (r.get("kit_id") or "").strip()
    return k if k else None

def svc_lunch_ok(s):
    r = svc_req.get(s, {})
    return (r.get("require_same_location_lunch_allowed") or "").strip().lower() == "yes"

def kit_handoff(k):
    r = kits.get(k, {})
    try:
        return float(r.get("handoff_minutes", 0) or 0)
    except (TypeError, ValueError):
        return 0.0

def kit_units(k):
    r = kits.get(k, {})
    try:
        return int(r.get("available_units", 1) or 1)
    except (TypeError, ValueError):
        return 1

def is_sensitive(t):
    a = task_info[t]["attrs"]
    ac = (a.get("acuity") or "").strip().lower()
    inf = (a.get("infection_status") or "").strip().lower()
    return ac == "high" or inf == "contact_precaution"

def is_contact(t):
    a = task_info[t]["attrs"]
    return (a.get("infection_status") or "").strip().lower() == "contact_precaution"

def is_high(t):
    a = task_info[t]["attrs"]
    return (a.get("acuity") or "").strip().lower() == "high"

def patient_territory(pid):
    return (pattrs.get(pid, {}).get("territory") or "").strip().lower()

def caregiver_territory(cid):
    return (profiles.get(cid, {}).get("territory") or "").strip().lower()

# eligible caregivers per task
elig = {}
for t in T:
    s = task_info[t]["service"]
    elig[t] = [c for c in C if s in set(careg[c]["abilities"])]

# handoff rules: map patient -> list of rules
handoff_by_patient = {}
for r in handoffs:
    handoff_by_patient.setdefault(r["patient_id"], []).append(r)

# ---------------- Model ----------------
model = Model("uhhc")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

x = {}   # x[c,i,t]
y = {}   # y[c,i,p]
a = {}   # arrival
d = {}   # departure
w = {}   # waiting
q = {}   # tardiness
for c in C:
    for i in range(1, NPOS + 1):
        a[(c, i)] = model.addVar(name=f"a_{c}_{i}", vtype="C", lb=0, ub=M)
        d[(c, i)] = model.addVar(name=f"d_{c}_{i}", vtype="C", lb=0, ub=M)
        w[(c, i)] = model.addVar(name=f"w_{c}_{i}", vtype="C", lb=0, ub=M)
        q[(c, i)] = model.addVar(name=f"q_{c}_{i}", vtype="C", lb=0, ub=M)
        for t in T:
            if c in elig[t]:
                x[(c, i, t)] = model.addVar(name=f"x_{c}_{i}_{t[0]}_{t[1]}", vtype="B")
        for p in patients:
            y[(c, i, p["id"])] = model.addVar(name=f"y_{c}_{i}_{p['id']}", vtype="B")

ot = {c: model.addVar(name=f"ot_{c}", vtype="C", lb=0, ub=M) for c in C}
skip = {}
for p in patients:
    if p["optional"]:
        skip[p["id"]] = model.addVar(name=f"skip_{p['id']}", vtype="B")

L = {c: model.addVar(name=f"L_{c}", vtype="B") for c in C}
lpos = {}
la = {}
ld = {}
for c in C:
    for i in range(1, NPOS + 1):
        lpos[(c, i)] = model.addVar(name=f"lpos_{c}_{i}", vtype="B")
        la[(c, i)] = model.addVar(name=f"la_{c}_{i}", vtype="C", lb=0, ub=M)
        ld[(c, i)] = model.addVar(name=f"ld_{c}_{i}", vtype="C", lb=0, ub=M)

# restock: rpos[c,i,k], ra, rd
restock_kits = list(restock_rules.keys())
rpos = {}
ra = {}
rd = {}
for c in C:
    for i in range(1, NPOS + 1):
        for k in restock_kits:
            rpos[(c, i, k)] = model.addVar(name=f"rpos_{c}_{i}_{k}", vtype="B")
            ra[(c, i, k)] = model.addVar(name=f"ra_{c}_{i}_{k}", vtype="C", lb=0, ub=M)
            rd[(c, i, k)] = model.addVar(name=f"rd_{c}_{i}_{k}", vtype="C", lb=0, ub=M)

# preference miss
pref_miss = model.addVar(name="pref_miss", vtype="B")

# max tardiness
Tmax = model.addVar(name="Tmax", vtype="C", lb=0, ub=M)

# ---------------- Constraints ----------------

# 1. Assignment
for t in T:
    pid = task_info[t]["patient"]
    if not task_info[t]["optional"]:
        model.addCons(quicksum(x[(c, i, t)] for c in C for i in range(1, NPOS + 1) if (c, i, t) in x) == 1, name=f"assign_{t[0]}_{t[1]}")
    else:
        model.addCons(quicksum(x[(c, i, t)] for c in C for i in range(1, NPOS + 1) if (c, i, t) in x) == 1 - skip[pid], name=f"assign_{t[0]}_{t[1]}")

# one task per position
for c in C:
    for i in range(1, NPOS + 1):
        model.addCons(quicksum(x[(c, i, t)] for t in T if (c, i, t) in x) <= 1, name=f"onetask_{c}_{i}")

# y links to x (patient of task)
for c in C:
    for i in range(1, NPOS + 1):
        for p in patients:
            pid = p["id"]
            ts_for_p = [t for t in T if task_info[t]["patient"] == pid]
            if not ts_for_p:
                continue
            model.addCons(y[(c, i, pid)] <= quicksum(x[(c, i, t)] for t in ts_for_p if (c, i, t) in x), name=f"ylink_{c}_{i}_{pid}")
            # if any task of p at position, y=1
            model.addCons(quicksum(x[(c, i, t)] for t in ts_for_p if (c, i, t) in x) <= len(ts_for_p) * y[(c, i, pid)], name=f"ylink2_{c}_{i}_{pid}")

# position monotonicity: position i used => position i-1 used (for i>1)
pos_used = {}
for c in C:
    for i in range(1, NPOS + 1):
        pos_used[(c, i)] = quicksum(x[(c, i, t)] for t in T if (c, i, t) in x)
for c in C:
    for i in range(2, NPOS + 1):
        model.addCons(pos_used[(c, i)] <= pos_used[(c, i - 1)], name=f"mono_{c}_{i}")

# 2. Sequencing: arrival of position i
# a[c,i] >= a[c,i-1] + d[c,i-1] - a[c,i-1] (service time prev) + travel(prev_loc, loc_i) + cleanup(prev) + handoff(prev kit, i kit) + restock(prev) - M*(1 - used_i) - M*(1 - used_{i-1})
# We use: a[c,i] >= a[c,i-1] + (d[c,i-1]-a[c,i-1]) + travel + cleanup + handoff + restock - M*(2 - used_i - used_{i-1})
# and a[c,i] <= ... + M*(2 - used_i - used_{i-1})
# For i=1: a[c,1] >= shift_start + travel(d0, loc) - M*(1-used)
for c in C:
    sh_start = float(careg[c]["working_shift"]["start"])
    sh_end = float(careg[c]["working_shift"]["end"])
    for i in range(1, NPOS + 1):
        used_i = pos_used[(c, i)]
        if i == 1:
            # a[c,1] = sh_start + travel(d0, loc_i) + w[c,1]
            for t in T:
                if (c, i, t) not in x:
                    continue
                info = task_info[t]
                loc = info["loc"]
                trav = float(dist[term_pts["d0"]][loc])
                model.addCons(a[(c, i)] >= sh_start + trav - M * (1 - x[(c, i, t)]), name=f"arr1lb_{c}_{t[0]}_{t[1]}")
                model.addCons(a[(c, i)] <= sh_start + trav + M * (1 - x[(c, i, t)]), name=f"arr1ub_{c}_{t[0]}_{t[1]}")
        else:
            used_ip1 = pos_used[(c, i - 1)]
            for t in T:
                if (c, i, t) not in x:
                    continue
                info = task_info[t]
                loc = info["loc"]
                # for each possible previous task t'
                for tp in T:
                    if (c, i - 1, tp) not in x:
                        continue
                    info_p = task_info[tp]
                    loc_p = info_p["loc"]
                    trav = float(dist[loc_p][loc])
                    svc_p = info_p["service"]
                    dur_p = float(info_p["dur"])
                    clean = svc_cleanup(svc_p) if is_contact(tp) else 0.0
                    # kit handoff
                    kp = svc_kit(svc_p)
                    ki = svc_kit(info["service"])
                    hand = 0.0
                    if kp and ki and kp == ki:
                        hand = kit_handoff(kp)
                    # restock at position i-1 (if any kit)
                    rest_term = 0.0
                    # restock duration added if restock at i-1
                    # We'll add restock time via rd-ra of restock vars at i-1
                    # Simplify: restock handled as separate position? No - restock is an event at d0 between tasks.
                    # Better: treat restock as consuming time at the position where it occurs.
                    # For now, add restock time as big-M term handled below via restock vars.
                    base = a[(c, i - 1)] + dur_p + trav + clean + hand
                    model.addCons(a[(c, i)] >= base - M * (2 - x[(c, i, t)] - x[(c, i - 1, tp)]), name=f"arrlb_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}")
                    model.addCons(a[(c, i)] <= base + M * (2 - x[(c, i, t)] - x[(c, i - 1, tp)]), name=f"arrub_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}")

# service: d[c,i] = a[c,i] + dur(t) for the task at position i
for c in C:
    for i in range(1, NPOS + 1):
        for t in T:
            if (c, i, t) not in x:
                continue
            dur = float(task_info[t]["dur"])
            model.addCons(d[(c, i)] >= a[(c, i)] + dur - M * (1 - x[(c, i, t)]), name=f"svclb_{c}_{i}_{t[0]}_{t[1]}")
            model.addCons(d[(c, i)] <= a[(c, i)] + dur + M * (1 - x[(c, i, t)]), name=f"svcub_{c}_{i}_{t[0]}_{t[1]}")

# waiting and tardiness: a[c,i] >= tw_start - M*(1-used); d[c,i] <= tw_end + q[c,i]
for c in C:
    for i in range(1, NPOS + 1):
        for t in T:
            if (c, i, t) not in x:
                continue
            info = task_info[t]
            tws = info["tw"]
            # multiple windows: use the union - take min start, max end for simplicity (windows are single in data)
            tw_start = min(wd["start"] for wd in tws)
            tw_end = max(wd["end"] for wd in tws)
            model.addCons(a[(c, i)] >= tw_start - M * (1 - x[(c, i, t)]), name=f"twlb_{c}_{i}_{t[0]}_{t[1]}")
            model.addCons(d[(c, i)] <= tw_end + q[(c, i)] + M * (1 - x[(c, i, t)]), name=f"twub_{c}_{i}_{t[0]}_{t[1]}")

# waiting definition: w[c,i] >= a[c,i] - (earliest possible start) ; approximate w as a - (prev end + travel) >= 0
# We define w[c,i] >= a[c,i] - (a[c,i-1] + dur_prev + travel) for i>1, and w[c,1] >= a[c,1] - (sh_start + travel)
# This is already captured in arrival equality; w is the slack. Use:
for c in C:
    sh_start = float(careg[c]["working_shift"]["start"])
    for i in range(1, NPOS + 1):
        if i == 1:
            for t in T:
                if (c, i, t) not in x:
                    continue
                loc = task_info[t]["loc"]
                trav = float(dist[term_pts["d0"]][loc])
                model.addCons(w[(c, i)] >= a[(c, i)] - (sh_start + trav) - M * (1 - x[(c, i, t)]), name=f"wlb1_{c}_{t[0]}_{t[1]}")
        else:
            for t in T:
                if (c, i, t) not in x:
                    continue
                loc = task_info[t]["loc"]
                for tp in T:
                    if (c, i - 1, tp) not in x:
                        continue
                    loc_p = task_info[tp]["loc"]
                    trav = float(dist[loc_p][loc])
                    dur_p = float(task_info[tp]["dur"])
                    svc_p = task_info[tp]["service"]
                    clean = svc_cleanup(svc_p) if is_contact(tp) else 0.0
                    kp = svc_kit(svc_p)
                    ki = svc_kit(task_info[t]["service"])
                    hand = kit_handoff(kp) if (kp and ki and kp == ki) else 0.0
                    model.addCons(w[(c, i)] >= a[(c, i)] - (a[(c, i - 1)] + dur_p + trav + clean + hand) - M * (2 - x[(c, i, t)] - x[(c, i - 1, tp)]), name=f"wlb_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}")

# shift end: last position departure + travel back <= sh_end + ot
# last position: for each c, the max i with a task. Use: for each i, d[c,i] + travel(loc_i, d0) <= sh_end + ot[c] + M*(1 - used_i) ... but only the LAST one matters.
# Simpler: for every position i, d[c,i] + travel <= sh_end + ot[c] + M*(1 - used_i) + M*(used of any later position)
# Even simpler: enforce for all i: if position i is the last used, return by shift end.
# Use: d[c,i] + travel(loc_i,d0) <= sh_end + ot[c] + M * (1 - x[c,i,t]) summed... 
# Practical approach: for each c and each i, for each t at i: d[c,i] + trav <= sh_end + ot[c] + M*(1 - x[c,i,t]) + M * (sum of used positions after i)
for c in C:
    sh_end = float(careg[c]["working_shift"]["end"])
    for i in range(1, NPOS + 1):
        later = quicksum(pos_used[(c, j)] for j in range(i + 1, NPOS + 1))
        for t in T:
            if (c, i, t) not in x:
                continue
            loc = task_info[t]["loc"]
            trav = float(dist[loc][term_pts["d0"]])
            model.addCons(d[(c, i)] + trav <= sh_end + ot[c] + M * (1 - x[(c, i, t)]) + M * later, name=f"shiftend_{c}_{i}_{t[0]}_{t[1]}")

# 3. Recovery eligibility
for c in C:
    h = history.get(c)
    if not h:
        continue
    try:
        ready = float(h["recovery_ready_minute"])
    except (ValueError, TypeError):
        continue
    applies = (h.get("applies_to") or "").strip().lower()
    if applies != "high_or_contact":
        continue
    for i in range(1, NPOS + 1):
        for t in T:
            if (c, i, t) not in x:
                continue
            if is_sensitive(t):
                model.addCons(a[(c, i)] >= ready * x[(c, i, t)], name=f"recov_{c}_{i}_{t[0]}_{t[1]}")

# 4. Territory and acuity caps
for c in C:
    prof = profiles.get(c, {})
    max_oot = int(prof.get("max_out_of_territory_patients", 0) or 0)
    max_ha = int(prof.get("max_high_acuity_patients", 0) or 0)
    cterr = caregiver_territory(c)
    oot_patients = [p["id"] for p in patients if patient_territory(p["id"]) != cterr]
    ha_patients = [p["id"] for p in patients if is_high((p["id"], p["required_services"][0]["service"]))]
    # out-of-territory: count distinct patients served out of territory
    model.addCons(quicksum(y[(c, i, pid)] for i in range(1, NPOS + 1) for pid in oot_patients) <= max_oot * NPOS, name=f"oot_{c}")
    # better: sum over positions of y for oot patients, but a patient appears in at most 1 position per caregiver (could be 2 if two services)
    # Use patient-level: for each oot patient, indicator served
    for pid in oot_patients:
        ts_for_p = [t for t in T if task_info[t]["patient"] == pid]
        if not ts_for_p:
            continue
        served = quicksum(x[(c, i, t)] for i in range(1, NPOS + 1) for t in ts_for_p if (c, i, t) in x)
        # served <= NPOS * indicator; we just cap total service-positions of oot patients
    model.addCons(quicksum(x[(c, i, t)] for i in range(1, NPOS + 1) for t in T if (c, i, t) in x and patient_territory(task_info[t]["patient"]) != cterr) <= max_oot * 2, name=f"oot2_{c}")
    model.addCons(quicksum(x[(c, i, t)] for i in range(1, NPOS + 1) for t in T if (c, i, t) in x and is_high(t)) <= max_ha * 2, name=f"ha_{c}")

# 5. Kit non-overlap (single unit)
# For each kit with 1 unit, any two tasks using it (possibly same or different caregiver) must not overlap in time, with handoff gap if consecutive.
# Model: for tasks t1, t2 using same kit k, if both assigned:
#   d[c1,i1,t1] + handoff <= a[c2,i2,t2]  OR  d[c2,i2,t2] + handoff <= a[c1,i1,t1]
# This is disjunctive; with small size, use big-M with ordering binaries.
kit_tasks = {}
for t in T:
    k = svc_kit(task_info[t]["service"])
    if k:
        kit_tasks.setdefault(k, []).append(t)

for k, ts in kit_tasks.items():
    if kit_units(k) >= 1:
        hand = kit_handoff(k)
        for idx1, t1 in enumerate(ts):
            for t2 in ts[idx1 + 1:]:
                # ordering binary o: 1 if t1 before t2
                o = model.addVar(name=f"kitord_{k}_{t1[0]}_{t1[1]}_{t2[0]}_{t2[1]}", vtype="B")
                for c1 in C:
                    for i1 in range(1, NPOS + 1):
                        if (c1, i1, t1) not in x:
                            continue
                        for c2 in C:
                            for i2 in range(1, NPOS + 1):
                                if (c2, i2, t2) not in x:
                                    continue
                                # if t1 before t2: d1 + hand <= a2
                                model.addCons(d[(c1, i1)] + hand <= a[(c2, i2)] + M * (1 - o) + M * (1 - x[(c1, i1, t1)]) + M * (1 - x[(c2, i2, t2)]), name=f"kitord1_{k}_{t1[0]}_{t1[1]}_{t2[0]}_{t2[1]}_{c1}_{c2}_{i1}_{i2}")
                                # if t2 before t1: d2 + hand <= a1
                                model.addCons(d[(c2, i2)] + hand <= a[(c1, i1)] + M * o + M * (1 - x[(c1, i1, t1)]) + M * (1 - x[(c2, i2, t2)]), name=f"kitord2_{k}_{t1[0]}_{t1[1]}_{t2[0]}_{t2[1]}_{c1}_{c2}_{i1}_{i2}")

# 6. Kit restock
# If caregiver c uses kit k at a contact-precaution patient at position i, and uses kit k again at a later position j>i,
# then a restock event at d0 must occur at some position r with i < r < j.
# Restock events consume time: we model restock as occurring "between" positions, adding restock_minutes to the gap.
# Simplification: if restock needed, add restock_minutes to the arrival of the later use.
# For each c, k, pair of positions (i, j) with i<j where t_i is contact use of k and t_j is any use of k:
#   a[c,j] >= d[c,i] + travel + ... + restock_minutes * (restock needed indicator)
# restock needed = 1 if there's a contact use of k at some position in (i_prev_contact, j] and no restock between.
# Given small scale, enforce: for each c, k, for each contact-use position i and later use position j (i<j):
#   either a restock position r exists with i<r<j, OR the later use is the first use (no earlier contact use).
# We add restock time directly: a[c,j] >= (earliest feasible) + restock_minutes if contact use before j without restock.
# Practical big-M approach:
for c in C:
    for k in restock_kits:
        rule = restock_rules[k]
        rest_min = float(rule["restock_minutes"])
        # contact tasks using kit k
        contact_uses = [t for t in T if svc_kit(task_info[t]["service"]) == k and is_contact(t)]
        all_uses = [t for t in T if svc_kit(task_info[t]["service"]) == k]
        for tc in contact_uses:
            for tj in all_uses:
                if tj == tc:
                    continue
                # positions
                for i in range(1, NPOS + 1):
                    if (c, i, tc) not in x:
                        continue
                    for j in range(i + 1, NPOS + 1):
                        if (c, j, tj) not in x:
                            continue
                        # restock must happen at some position r in (i, j)
                        restock_vars = [rpos[(c, r, k)] for r in range(i + 1, j)]
                        if not restock_vars:
                            # no room for restock => forbid this combination
                            model.addCons(x[(c, i, tc)] + x[(c, j, tj)] <= 1, name=f"restockforbid_{c}_{k}_{tc[0]}_{tc[1]}_{tj[0]}_{tj[1]}_{i}_{j}")
                        else:
                            model.addCons(quicksum(restock_vars) >= x[(c, i, tc)] + x[(c, j, tj)] - 1, name=f"restockreq_{c}_{k}_{tc[0]}_{tc[1]}_{tj[0]}_{tj[1]}_{i}_{j}")

# restock time consumption: if restock at position r, it adds rest_min to the route.
# Model: restock at position r means the caregiver is at d0 for rest_min minutes.
# We enforce: ra[c,r,k] >= d[c,r-1] + travel(loc_{r-1}, d0) - M*(1-rpos)
#             rd[c,r,k] = ra + rest_min
#             a[c,r+1] >= rd + travel(d0, loc_{r+1}) - M*(1-rpos)
# This is complex; given the small instance, we add restock time as a penalty-free big-M addition to arrival.
# Simplified: for each c, r, k: if rpos[c,r,k]=1, then the route "pauses" for rest_min at d0.
# We add: for position r+1, a[c,r+1] >= a[c,r] + dur_r + travel + rest_min*rpos - M*(...)
# To keep tractable, we add rest_min to the waiting variable at position r+1 when restock at r.
for c in C:
    for k in restock_kits:
        rule = restock_rules[k]
        rest_min = float(rule["restock_minutes"])
        for r in range(1, NPOS):
            for j in range(r + 1, NPOS + 1):
                for tj in T:
                    if (c, j, tj) not in x:
                        continue
                    # if restock at r and task at j, add rest_min to waiting at j (approx)
                    model.addCons(w[(c, j)] >= rest_min * rpos[(c, r, k)] - M * (1 - pos_used[(c, j)]), name=f"restocktime_{c}_{k}_{r}_{j}_{tj[0]}_{tj[1]}")

# restock location: restock at d0 (terminal). ra >= d[c,r-1] + travel - M*(1-rpos); rd = ra + rest_min
for c in C:
    for k in restock_kits:
        rule = restock_rules[k]
        rest_min = float(rule["restock_minutes"])
        for r in range(1, NPOS + 1):
            model.addCons(rd[(c, r, k)] >= ra[(c, r, k)] + rest_min - M * (1 - rpos[(c, r, k)]), name=f"restdur1_{c}_{k}_{r}")
            model.addCons(rd[(c, r, k)] <= ra[(c, r, k)] + rest_min + M * (1 - rpos[(c, r, k)]), name=f"restdur2_{c}_{k}_{r}")

# 7. Handoff rules
for r in handoffs:
    pid = r["patient_id"]
    s1 = r["first_service_id"]
    s2 = r["second_service_id"]
    min_gap = float(r["min_gap_minutes"])
    max_gap = float(r["max_gap_minutes"])
    relation = r["caregiver_relation"].strip().lower()
    t1 = (pid, s1)
    t2 = (pid, s2)
    if t1 not in TIDX or t2 not in TIDX:
        continue
    # ordering: t1 before t2 (enforced by gap >= min_gap >= 0)
    for c1 in C:
        for i1 in range(1, NPOS + 1):
            if (c1, i1, t1) not in x:
                continue
            for c2 in C:
                for i2 in range(1, NPOS + 1):
                    if (c2, i2, t2) not in x:
                        continue
                    # gap = a[c2,i2] - d[c1,i1]
                    # min_gap <= gap <= max_gap
                    model.addCons(a[(c2, i2)] - d[(c1, i1)] >= min_gap - M * (1 - x[(c1, i1, t1)]) - M * (1 - x[(c2, i2, t2)]), name=f"handoff_min_{pid}_{c1}_{c2}_{i1}_{i2}")
                    model.addCons(a[(c2, i2)] - d[(c1, i1)] <= max_gap + M * (1 - x[(c1, i1, t1)]) + M * (1 - x[(c2, i2, t2)]), name=f"handoff_max_{pid}_{c1}_{c2}_{i1}_{i2}")
                    if relation == "different" and c1 == c2:
                        model.addCons(x[(c1, i1, t1)] + x[(c2, i2, t2)] <= 1, name=f"handoff_diff_{pid}_{c1}_{c2}_{i1}_{i2}")

# 8. Lunch
for c in C:
    has_lunch = bool(careg[c]["lunch_break"])
    if not has_lunch:
        model.addCons(L[c] == 0, name=f"nolunch_{c}")
        continue
    # exactly one lunch position if L[c]=1
    model.addCons(quicksum(lpos[(c, i)] for i in range(1, NPOS + 1)) == L[c], name=f"lunchone_{c}")
    # lunch at position i: at terminal d0 or at a patient home on the route
    # lunch time within [180, 360], duration >= 30
    lw_start = float(lunch_win["start"])
    lw_end = float(lunch_win["end"])
    lw_min = float(lunch_win["min_duration"])
    for i in range(1, NPOS + 1):
        model.addCons(la[(c, i)] >= lw_start - M * (1 - lpos[(c, i)]), name=f"lunchstart_{c}_{i}")
        model.addCons(ld[(c, i)] <= lw_end + M * (1 - lpos[(c, i)]), name=f"lunchend_{c}_{i}")
        model.addCons(ld[(c, i)] >= la[(c, i)] + lw_min - M * (1 - lpos[(c, i)]), name=f"lunchdur_{c}_{i}")
        # lunch at position i means the caregiver is at d0 or at a patient home
        # If at patient home p, then y[c,i,p] must be 1 and the service at i allows same-location lunch
        # Simplify: lunch at position i is at d0 (terminal) OR at the patient of position i (if allowed)
        # We allow lunch at d0 always; at patient home only if the task at i has svc_lunch_ok
        # For simplicity, allow lunch at d0 (always feasible) - this is conservative
        # Lunch at d0: la >= d[c,i-1] + travel(loc_{i-1}, d0) - M*(1-lpos)
        #             ld <= a[c,i+1] - travel(d0, loc_{i+1}) - M*(1-lpos)
        # This is complex; given small instance, we allow lunch at d0 and enforce timing via big-M
        if i > 1:
            for tp in T:
                if (c, i - 1, tp) not in x:
                    continue
                loc_p = task_info[tp]["loc"]
                trav = float(dist[loc_p][term_pts["d0"]])
                dur_p = float(task_info[tp]["dur"])
                model.addCons(la[(c, i)] >= a[(c, i - 1)] + dur_p + trav - M * (1 - lpos[(c, i)]) - M * (1 - x[(c, i - 1, tp)]), name=f"luncharr_{c}_{i}_{tp[0]}_{tp[1]}")
        if i < NPOS:
            for tj in T:
                if (c, i + 1, tj) not in x:
                    continue
                loc_j = task_info[tj]["loc"]
                trav = float(dist[term_pts["d0"]][loc_j])
                model.addCons(ld[(c, i)] <= a[(c, i + 1)] - trav - M * (1 - lpos[(c, i)]) - M * (1 - x[(c, i + 1, tj)]), name=f"lunchdep_{c}_{i}_{tj[0]}_{tj[1]}")

# 9. Preference: p8 preferred c2
p8_served = model.addVar(name="p8_served", vtype="B")
p8_by_c2 = model.addVar(name="p8_by_c2", vtype="B")
t_p8 = ("p8", "s4")
if t_p8 in TIDX:
    model.addCons(p8_served <= quicksum(x[(c, i, t_p8)] for c in C for i in range(1, NPOS + 1) if (c, i, t_p8) in x), name="p8served_lb")
    model.addCons(quicksum(x[(c, i, t_p8)] for c in C for i in range(1, NPOS + 1) if (c, i, t_p8) in x) <= p8_served, name="p8served_ub")
    model.addCons(p8_by_c2 <= quicksum(x[("c2", i, t_p8)] for i in range(1, NPOS + 1) if ("c2", i, t_p8) in x), name="p8c2_lb")
    model.addCons(quicksum(x[("c2", i, t_p8)] for i in range(1, NPOS + 1) if ("c2", i, t_p8) in x) <= p8_by_c2, name="p8c2_ub")
    model.addCons(pref_miss >= p8_served - p8_by_c2, name="prefmiss")

# 10. Max tardiness
for c in C:
    for i in range(1, NPOS + 1):
        model.addCons(Tmax >= q[(c, i)], name=f"tmax_{c}_{i}")

# ---------------- Objective ----------------
W_travel = float(cost.get("travel_time", 1))
W_tard = float(cost.get("total_tardiness", 8))
W_maxtard = float(cost.get("highest_tardiness", 5))
W_wait = float(cost.get("total_waiting_time", 7))
W_ot = float(cost.get("total_extra_time", 8))
W_pref = float(cost.get("caregiver_preferences", 7))
W_opt = float(cost.get("optional_patients", 200))
W_lunch = float(cost.get("missed_lunch_break", 60))

# travel: sum of travel segments. Approximate via waiting + tardiness + service times vs shift.
# Travel time = (last departure + return travel) - shift_start - sum(service times) - sum(waiting) - sum(tardiness) - lunch time - restock time
# Simpler: compute travel as sum over consecutive positions of dist[loc_i, loc_{i+1}] * x
# We add travel as: for each c, i, t, tp: dist[loc_tp, loc_t] * x[c,i,tp] * x[c,i+1,t]
# This is bilinear; linearize with z[c,i,tp,t] <= x[c,i,tp], z <= x[c,i+1,t], z >= x[c,i,tp]+x[c,i+1,t]-1
# Given small size, do it.
travel_terms = []
for c in C:
    sh_start = float(careg[c]["working_shift"]["start"])
    # first leg: d0 -> loc_i
    for i in range(1, NPOS + 1):
        for t in T:
            if (c, i, t) not in x:
                continue
            loc = task_info[t]["loc"]
            trav = float(dist[term_pts["d0"]][loc])
            travel_terms.append(trav * x[(c, i, t)])
    # consecutive legs
    for i in range(1, NPOS):
        for t in T:
            if (c, i, t) not in x:
                continue
            loc_t = task_info[t]["loc"]
            for tp in T:
                if (c, i + 1, tp) not in x:
                    continue
                loc_tp = task_info[tp]["loc"]
                trav = float(dist[loc_t][loc_tp])
                z = model.addVar(name=f"z_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}", vtype="B")
                model.addCons(z <= x[(c, i, t)], name=f"z1_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}")
                model.addCons(z <= x[(c, i + 1, tp)], name=f"z2_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}")
                model.addCons(z >= x[(c, i, t)] + x[(c, i + 1, tp)] - 1, name=f"z3_{c}_{i}_{t[0]}_{t[1]}_{tp[0]}_{tp[1]}")
                travel_terms.append(trav * z)
    # return leg: loc_i -> d0 (last position)
    # Approximate: add return travel for each position weighted by (1 - later positions)
    for i in range(1, NPOS + 1):
        for t in T:
            if (c, i, t) not in x:
                continue
            loc = task_info[t]["loc"]
            trav = float(dist[loc][term_pts["d0"]])
            # return travel counted if no later position used
            later = quicksum(pos_used[(c, j)] for j in range(i + 1, NPOS + 1))
            # z_ret = 1 if position i is last: z_ret >= x[c,i,t] - later, z_ret <= x[c,i,t]
            z_ret = model.addVar(name=f"zret_{c}_{i}_{t[0]}_{t[1]}", vtype="B")
            model.addCons(z_ret <= x[(c, i, t)], name=f"zret1_{c}_{i}_{t[0]}_{t[1]}")
            model.addCons(z_ret >= x[(c, i, t)] - later, name=f"zret2_{c}_{i}_{t[0]}_{t[1]}")
            travel_terms.append(trav * z_ret)

obj_terms = []
obj_terms.extend(travel_terms)
for c in C:
    for i in range(1, NPOS + 1):
        obj_terms.append(W_tard * q[(c, i)])
        obj_terms.append(W_wait * w[(c, i)])
    obj_terms.append(W_ot * ot[c])
obj_terms.append(W_maxtard * Tmax)
obj_terms.append(W_pref * pref_miss)
for p in patients:
    if p["optional"]:
        obj_terms.append(W_opt * skip[p["id"]])
for c in C:
    if bool(careg[c]["lunch_break"]):
        obj_terms.append(W_lunch * (1 - L[c]))

model.setObjective(quicksum(obj_terms), sense="minimize")

# ---------------- Solve ----------------
model.hideOutput()
try:
    model.optimize()
except Exception as e:
    print(f"Solver error: {e}")

status = model.getStatus()
print(f"Status: {status}")
nsols = model.getNSols()
print(f"Number of solutions: {nsols}")

best_sol = None
if nsols > 0:
    best_sol = model.getBestSol()
    obj_val = model.getObjVal()
    print(f"Objective: {obj_val}")
else:
    obj_val = None
    print("No solution found.")

# ---------------- Extract solution ----------------
routes = []
if best_sol is not None:
    for c in C:
        locations = []
        for i in range(1, NPOS + 1):
            # find task at position i
            task_at_i = None
            for t in T:
                if (c, i, t) in x:
                    val = model.getVal(x[(c, i, t)])
                    if val is not None and val > 0.5:
                        task_at_i = t
                        break
            if task_at_i is not None:
                arr = model.getVal(a[(c, i)])
                dep = model.getVal(d[(c, i)])
                if arr is not None and dep is not None:
                    locations.append({
                        "patient": task_info[task_at_i]["patient"],
                        "service": task_info[task_at_i]["service"],
                        "arrival_time": round(arr, 8),
                        "departure_time": round(dep, 8),
                    })
            # lunch at position i
            lval = model.getVal(lpos[(c, i)])
            if lval is not None and lval > 0.5:
                lar = model.getVal(la[(c, i)])
                ldep = model.getVal(ld[(c, i)])
                # determine lunch location: d0 or patient home
                # check if y[c,i,p] is 1 for some p
                lunch_loc = "d0"
                for p in patients:
                    yval = model.getVal(y[(c, i, p["id"])])
                    if yval is not None and yval > 0.5:
                        # check if service at i allows same-location lunch
                        if task_at_i is not None and svc_lunch_ok(task_info[task_at_i]["service"]):
                            lunch_loc = p["id"]
                            break
                if lar is not None and ldep is not None:
                    locations.append({
                        "patient": lunch_loc,
                        "service": "lunch_break",
                        "arrival_time": round(lar, 8),
                        "departure_time": round(ldep, 8),
                    })
            # restock at position i
            for k in restock_kits:
                rval = model.getVal(rpos[(c, i, k)])
                if rval is not None and rval > 0.5:
                    rar = model.getVal(ra[(c, i, k)])
                    rdep = model.getVal(rd[(c, i, k)])
                    if rar is not None and rdep is not None:
                        locations.append({
                            "patient": "d0",
                            "service": f"kit_restock:{k}",
                            "arrival_time": round(rar, 8),
                            "departure_time": round(rdep, 8),
                        })
        if locations:
            routes.append({"caregiver_id": c, "locations": locations})

# ---------------- Validate ----------------
print("\n--- Validation ---")
# Check required patients
for p in patients:
    if not p["optional"]:
        for rs in p["required_services"]:
            found = False
            for r in routes:
                for loc in r["locations"]:
                    if loc["patient"] == p["id"] and loc["service"] == rs["service"]:
                        found = True
            if not found:
                print(f"WARNING: required service {p['id']}/{rs['service']} not found in solution")
            else:
                print(f"OK: {p['id']}/{rs['service']} assigned")

# Check time windows
for r in routes:
    for loc in r["locations"]:
        if loc["service"] in ("lunch_break",) or loc["service"].startswith("kit_restock:"):
            continue
        pid = loc["patient"]
        p = next((pp for pp in patients if pp["id"] == pid), None)
        if p:
            tw_end = max(wd["end"] for wd in p["time_windows"])
            if loc["departure_time"] > tw_end + 0.01:
                print(f"WARNING: {pid} service end {loc['departure_time']} > tw_end {tw_end} (tardiness)")
            else:
                print(f"OK: {pid} service end {loc['departure_time']} <= tw_end {tw_end}")

# Check kit restock
for r in routes:
    used_kits_contact = set()
    for loc in r["locations"]:
        if loc["service"].startswith("kit_restock:"):
            k = loc["service"].split(":")[1]
            used_kits_contact.discard(k)
        elif loc["service"] not in ("lunch_break",):
            k = svc_kit(loc["service"])
            if k and k in restock_rules:
                pid = loc["patient"]
                if is_contact((pid, loc["service"])):
                    if k in used_kits_contact:
                        print(f"WARNING: kit {k} reused after contact without restock for {r['caregiver_id']}")
                    used_kits_contact.add(k)

print("--- Validation complete ---")

# ---------------- Write solution ----------------
os.makedirs("/app/submissions", exist_ok=True)
solution = {"routes": routes}
with open(OUT, "w") as f:
    json.dump(solution, f, indent=2)
print(f"\nSolution written to {OUT}")
print(f"Routes: {len(routes)}")
for r in routes:
    print(f"  {r['caregiver_id']}: {len(r['locations'])} locations")

model.free()
